function UINavigatorBar:Start()
    --这里可以做一些动画的逻辑
    self.__everythingChangeHandler = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.__ChangeCurrencyNum))
    self.__EventChangeTitleName = Events.AddListener(Constants.EventNames.EventChangeNavigatorBarTitleName, Bind(self, self.OnEventChangeTitleName))
    self.backEventHandler = Events.AddListener(ANDROID_NATIVE_BACK_ACTION, function()
        if isNull(UIModule.CurrentScreen) then 
            return
        end 

        --- 微缩世界跑酷 不需要本返回键
        if isNotNull(UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.ParkourGameMainDialog)) then 
            return
        end 

        ---执行返回的逻辑
        if UIModule.CurrentScreen.Argument.id == Constants.UITypeIds.UISceneHome then
            local length = UIModule.CurrentScreen.dialogs.Count
            local count = UIModule.Instance.uiPages.Count
            if not (length == 1 and count == 0) then
                ---@type Engine.UI.UIRaycastBlocker
                local blocker = UIRaycastBlocker.Instance
                if blocker.ConditionsCount == 0 and KTool.IsActiveInHierarchy(self.controller.gameObject) and CS.UINavigationBarRoot.Instance.CacheCanvas.enabled then
                    if GuideUtils.IsInGuiding() then
                        return
                    end
                    local secondConfirm = UIModule.RootCanvas.transform.parent:Find("SecondConfirmPopUp")
                    if not isNull(secondConfirm) then
                        ---@type UISecondConfirm
                        local env = CfUtils.GetLuaScr(secondConfirm.gameObject, "Game.Behaviours.UISecondConfirm")
                        if env then
                            ---@type Engine.UI.UIEventProxy
                            local eventProxy = KTool.GetComponent(env.BtnCancel.gameObject, typeof(UIEventProxy))
                            if eventProxy.onPointerClick then
                                eventProxy.onPointerClick()
                            end
                        end
                        return
                    end
                    self:OnBackButtonAction()
                end
            else
                ---当前在主界面的情况下
                ---@type Engine.UI.UIRaycastBlocker
                local blocker = UIRaycastBlocker.Instance
                if blocker.ConditionsCount == 0 then
                    local dialog = UIModule.CurrentScreen:LastDialog()
                    if dialog and dialog.Argument.id == Constants.UITypeIds.UIHomeView then
                        local secondConfirm = UIModule.RootCanvas.transform.parent:Find("SecondConfirmPopUp")
                        if not isNull(secondConfirm) then
                            ---@type UISecondConfirm
                            local env = CfUtils.GetLuaScr(secondConfirm.gameObject, "Game.Behaviours.UISecondConfirm")
                            if env then
                                ---@type Engine.UI.UIEventProxy
                                local eventProxy = KTool.GetComponent(env.BtnCancel.gameObject, typeof(UIEventProxy))
                                if eventProxy.onPointerClick then
                                    eventProxy.onPointerClick()
                                end
                            else
                                KTool.SetActive(secondConfirm.gameObject, false)
                                KTool.SafeDelete(secondConfirm.gameObject)
                            end
                            return
                        end
                        local _funcBackToLogin = function()
                            GameUtils.BackToGameStart()
                        end
                        GameUtils.SecondConfirm(localize('是否要退出游戏重新登录'), function()
                            _funcBackToLogin()
                        end)
                    end
                end
            end
        end
    end)
end

