---UpdateHealthNode
---更新资源条的数据
---体力的数量
---@param goodsIds number[] @ {goodsId, goodsId}
---@param isCache boolean @ 是否缓存道具id
---@param healthNodePos Vector2
function UINavigatorBar:UpdateHealthNodes(goodsIds, isCache, healthNodePos)
    if goodsIds == nil then
        goodsIds = { Constants.Currency.FreeDiamondId, Constants.Currency.GoldId, Constants.Currency.HpId }
    end
    if type(goodsIds) == 'string' then
        goodsIds = parse_strings(goodsIds, ';')
    end
    if isCache then
        self.cacheGoodsIds = goodsIds
    end
    if healthNodePos then
        self.originHealthNodeBgPos = self.HealthNode.anchoredPosition
        if self.HealthNodeBgLayoutGroup then
            self.HealthNodeBgLayoutGroup.enabled = false
        end
        self.HealthNode.anchoredPosition = healthNodePos
    end
    self.goodsIds = goodsIds
    local healthNodes = self.healthNodes
    local forTimes = math.max(#healthNodes, #goodsIds)
    for i = 1, forTimes do
        local healthNode = healthNodes[i]
        local goodsId = goodsIds[i]
        KTool.SetActive(healthNode.gameObject, goodsId ~= nil)
        if goodsId then
            self:ChangeNode(healthNode, goodsId, true)
        end
    end
end

function UINavigatorBar:RestoreHealthNodes()
    if self.originHealthNodeBgPos then
        if self.HealthNodeBgLayoutGroup then
            self.HealthNodeBgLayoutGroup.enabled = true
        end
        self.HealthNode.anchoredPosition = self.originHealthNodeBgPos
        self.originHealthNodeBgPos = nil
    end

    if self.cacheGoodsIds then
        self:UpdateHealthNodes(self.cacheGoodsIds)
        self.cacheGoodsIds = nil
    end
end

---__ChangeCurrencyNum
---没有道具id 刷所有
---@param goodsId number 道具Id
function UINavigatorBar:__ChangeCurrencyNum(goodsId)
    --printInfo(goodsId)
    if goodsId == nil then
        self:UpdateHealthNodes(self.goodsIds)
        return
    end
    goodsId = checkNumber(goodsId)
    local index
    for i, v in ipairs(self.goodsIds) do
        if checkNumber(v) == goodsId then
            index = i
            break
        end
    end

    --printInfo(index)
    if index == nil then
        return
    end

    local healthNodes = self.healthNodes
    if goodsId then
        self:ChangeNode(healthNodes[index], goodsId, true)
    end
end

---__EventChange
--- 私有函数 道具变化的事件回调
---然后刷新资源条相关
---@param healthNode UnityEngine.Transform
---@param goodsId number
---@param updateIcon boolean
function UINavigatorBar:ChangeNode(healthNode, goodsId, updateIcon)
    goodsId = checkNumber(goodsId)
    local assetNodeMB = GetLuaBehaviour(healthNode.gameObject, AssetNodeMB)
    if not KTool.IsNull(assetNodeMB) then
        if isNull(assetNodeMB.Env) then
            assetNodeMB:Init()
        end
        assetNodeMB.Env:FreshAssetByGoodsId(goodsId, updateIcon)
    end
end

--- 设置资源栏按钮的可点击状态
---@param state any
function UINavigatorBar:SetHealthNodesCanClick(state)
    local nodesCount = #self.healthNodes
    for i = 1, nodesCount, 1 do
        local node = self.healthNodes[i]
        local assetNodeMB = GetLuaBehaviour(node.gameObject, AssetNodeMB)
        if not KTool.IsNull(assetNodeMB) then
            if isNull(assetNodeMB.Env) then
                assetNodeMB:Init()
            end
            assetNodeMB.Env:SetCanClick(state)
        end
    end
end

local ANIM_TIME = 0.66

function UINavigatorBar:ShowBackAnimation()
    if self.hideBlackCo then
        self.hideBlackCo:Kill()
    end
    if self.isStart then
        return
    end
    self.isStart = true
    --if not isNull(self.backAnimationGo) then
    --    ---@type UnityEngine.Animation
    --    local animation = KTool.GetComponent(self.backAnimationGo, typeof(CS.UnityEngine.Animation))
    --    if not isNull(animation) then
    --        animation:Play(ExitAnimationName)
    --    end
    --end
    cs_coroutine.start(function()
        if not isNull(self.backAnimationGo) then
            KTool.SetActive(self.backAnimationGo, true)
        end
        ---@type UnityEngine.Animation
        local animation = KTool.GetComponent(self.backAnimationGo, typeof(CS.UnityEngine.Animation))
        if not isNull(animation) then
            animation:Play(ExitAnimationName)
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(ANIM_TIME))
        if not isNull(self.backAnimationGo) then
            KTool.SetActive(self.backAnimationGo, false)
        end
        self.isStart = false
    end)
end

--- 遮黑
---@param duration any
function UINavigatorBar:ShowBlackDuration(inDuration, duration, outDuration, targetColor)
    if self.isStart then
        return
    end

    cs_coroutine.start(function()
        if not isNull(self.backAnimationGo) then
            self.isStart = true
            targetColor = targetColor or Color.black

            KTool.SetActive(self.backAnimationGo, true)

            ---@type UnityEngine.Animation
            local animation = KTool.GetComponent(self.backAnimationGo, typeof(CS.UnityEngine.Animation))
            if not isNull(animation) then
                animation.enabled = false
            end

            -- 淡入
            local TF_Img = self.backAnimationGo.transform:GetChild(0)
            local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
            local color = DeepCopy(targetColor)
            color.a = 0
            img.color = color
            if inDuration > 0 then
                img:DOFade(1, inDuration)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(inDuration))
            end
            img.color = targetColor

            -- 遮黑
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(duration))

            -- 淡出
            local TF_Img = self.backAnimationGo.transform:GetChild(0)
            local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
            img.color = targetColor
            if outDuration > 0 then
                img:DOFade(0, outDuration)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(outDuration))
            end

            KTool.SetActive(self.backAnimationGo, false)

            if not isNull(animation) then
                animation.enabled = true
            end
            self.isStart = false
        end
    end)
end

local function PeekPage()
    ---@type Engine.UI.UIModule
    local instance = UIModule.Instance
    local listPage = instance.uiPages
    local arguments
    if listPage.Count > 0 then
        ---@type Engine.UI.UIPage
        local pages = listPage[listPage.Count - 1]
        if isNull(pages.uiArguments) or pages.uiArguments.Count == 0 then
            arguments = PeekPage()
        else
            arguments = pages.uiArguments
        end
    end
    return arguments
end

function UINavigatorBar:OnBackButtonAction()
    ---返回防止以后用，添加一个返回按钮事件
    if not self.isSmallPackage then
        -- 打断角色语音
        CriWareUtils.PlayVoice("Audio/UI_Menu", "empty")
    end
    Events.Broadcast(Constants.EventNames.EventUINavigatorBackBar)
    local dialog = UIModule.CurrentScreen:LastDialog()
    if dialog then
        local id = dialog.Argument.id
        local isExecute = true
        ---@type Backpack
        local env = dialog.Env
        if env and env.isBatch then
            isExecute = false
        end
        if isExecute then
            dialog:SetSortOrder(3)
        end
        -- 该黑屏动作在真机上会导致更长时间的黑屏，暂时先注释掉。
        -- local tableFile = SettingMgr:Get(AutoIds.IdSetting22)
        -- local row = tableFile:GetByPrimaryKey(id)
        -- local backAni = parse_number(row, "backAni")
        -- if backAni == 1 and isExecute then
        --     self:ShowBackAnimation()
        -- end
    end
    if not isNull(self.__thirdButtonAction) then
        local arguments = PeekPage()
        if arguments and arguments.Count > 1 and dialog.Argument.hasExcluded then
            ---多个的情况下通用显示猫头吧
            GameUtils.ShowBlackOverlay(nil, function()
                cs_coroutine.yield_return(self.__thirdButtonAction(true))
            end)
        else
            CfUtils.StartCoroutineWithBlocker(self.__thirdButtonAction)
        end
    else
        local length = UIModule.CurrentScreen.dialogs.Count
        local count = UIModule.Instance.uiPages.Count
        if length > 0 then
            local env = dialog.Env
            if env and env.OnBackAction then
                ---特殊处理下
                env:OnBackAction()
            end
            --- 自定义后退按钮行为，注意：大概率你需要要配合 self.isBatch = true 的定义使用
            if env and env.HandleBackAction then
                env:HandleBackAction()
            else
                local arguments = PeekPage()
                if arguments and arguments.Count > 1 and dialog.Argument.hasExcluded then
                    ---多个的情况下通用显示猫头吧
                    GameUtils.ShowBlackOverlay(nil, function()
                        cs_coroutine.yield_return(UIModule.BackDialog())
                    end)
                else
                    UIModule.BackDialog()
                end
            end
            --[[          if count <= 0 then
                          if KCookie.Get(Constants.UICacheDataKeys.IS_PRE_DOWNLOAD) == 1 then
                              --UIModule.OpenDialog({ id = Constants.UITypeIds.PreDownloadEntryMainDialog })
                          elseif length <= 1 then
                              ---小于长度小于1的时候，表现关掉当页面后没在新页面，需要打开一个页面
                              UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView })
                          end
                      end]]
        else
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView })
        end
    end
end

