---__ExecuteJump
---执行跳转的模块的逻辑
---@param moduleId number
function UINavigatorBar:__ExecuteJump(moduleId)
    --CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_jump_cat)
    ---@type Engine.UI.UIRaycastBlocker
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("__ExecuteJump")
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    xTry(function()
        cs_coroutine.start(function()
            ---@type TableML.TableFileRow
            local row = goodsConfMgr:GetJumpModuleRow(moduleId)
            if row then
                cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, {}, 0, true))
            end
            blocker:RemoveCondition("__ExecuteJump")
        end)
    end, function()
        print_to_file(debug.traceback())
        blocker:RemoveCondition("__ExecuteJump")
    end)

end

function UINavigatorBar:ExecuteBackHomeAction()
    --- 以前 UIMainHomeSceneFocusShowEventName 先显示主场景 其他界面如果有 PlanarReflections 先enable 主场景的PlanarReflections 在disable 其他界面 PlanarReflections
    --- PlanarReflections又是全局的 进而导致 回到主界面 PlanarReflections 出问题
    --- 这种全局状态的启用 如果以前是启用状态 应该先disable 先发个事件 对应的界面自己处理
    Events.Broadcast(Constants.EventNames.ExecuteBackHome)
    ---@type Engine.UI.UIRaycastBlocker
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("GOHomeBlocker")
    ---显示出主界面的元素再打开页面
    return cs_coroutine.start(function()
        local screenId = UIModule.CurrentScreen.Argument.id
        if screenId ~= Constants.UITypeIds.UISceneHome then
            if screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene then
                xTry(function()
                    CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
                    GameUtils.ShowBlackOverlay(nil, function()
                        local co = cs_coroutine.start(function()
                            ---关闭所有的窗口
                            xTry(function()
                                local needWaitDialogClose = false
                                local coWait = CoWait.Start()
                                for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                                    local isRemove = string.isEmpty(v.Argument.extra)
                                    local coClose = UIModule.CloseDialog(v, isRemove)
                                    if not isNull(coClose) then
                                        needWaitDialogClose = true
                                        coWait:Coroutine(coClose)
                                    end
                                end
                                UIModule.CurrentScreen.dialogs:Clear()
                                while needWaitDialogClose and not coWait.IsFinish do
                                    coroutine.yield()
                                end
                                CS.Engine.UI.UIModule.ResetStack()
                            end)
                            cs_coroutine.yield_return(UIModule.OpenScreen(UIArgs(Constants.UITypeIds.UISceneHome), true, nil))
                            ---@type XMainHome
                            local env = UIModule.CurrentScreen.Env
                            cs_coroutine.yield_return(env:AsyncLoadingResources())
                            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
                            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.Normal
                        end)
                        coroutine.yield(co)
                    end)
                end, function()
                    UIRaycastBlocker:RemoveCondition("GOHomeBlocker")
                end)
            elseif screenId == Constants.UITypeIds.FairylandSceneEnter then
                local FairylandUtils = import("Game.Fairyland.FairylandUtils")
                FairylandUtils.CurrentNearIndex = 0

                local parameters = {
                    isBackToHomeScene = true,
                    isSaveSceneRecord = true, 
                    isReleaseBattle   = true,
                    extraUIPages = {
                        UIArgs(Constants.UITypeIds.UIHomeView),
                    }
                }
                UIModule.ResetStack()
                GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UISceneHome, parameters), nil, Constants.LoadingType.Others, false, true)
            else
                local FishingMgr = import('Game.UI.Fishing.FishingMgr')
                local id = FishingMgr:GetInstance()._curFishPlaceId
                if checkNumber(id) > 0 then
                    FishingMgr:GetInstance():SetIsGoHome(true)
                    coroutine.yield(FishingMgr:GetInstance():Clear())
                end
                ---重置堆栈
                --UIModule.ResetStack()
                ---当前场景不是主界面 去掉当前场景的所有ui
                UIModule.BackScreenStackIds()
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, { { id = Constants.UITypeIds.UIHomeView } }, Constants.LoadingType.MainHome, false)
            end
        else
            local dialogs = UIModule.CurrentScreen.dialogs
            local topDialog = UIModule.CurrentScreen:LastDialog()
            if topDialog.Env and topDialog.Env.OnCaptureAction then
                ---调用下截图的方法
                topDialog.Env:OnCaptureAction()
                cs_coroutine.yield_return()
            end
            --for i, dialog in pairs(dialogs) do
            --    ---@type Engine.UI.UILuaDialog
            --    if dialog ~= topDialog then
            --        cs_coroutine.yield_return(UIModule.CloseDialog(dialog))
            --    end
            --end
            local coWait = CoWait.Start()
            local needWaitDialogClose = false
            for i, dialog in support.list_ipairs(dialogs) do
                ---@type Engine.UI.UILuaDialog
                if dialog ~= topDialog then
                    needWaitDialogClose = true
                    coWait:Coroutine(UIModule.CloseDialog(dialog, true))
                end
            end
            while needWaitDialogClose and not coWait.IsFinish do
                coroutine.yield()
            end
            ---重置堆栈
            UIModule.ResetStack()
            --if not (topDialog.Env and topDialog.Env.OnCaptureAction) then
            --    UIModule.CloseDialog(topDialog)
            --end
            local env = topDialog.Env
            if env and env.OnBackAction then
                ---特殊处理下
                env:OnBackAction()
            end
            if topDialog.Env and topDialog.Env.OnCaptureAction then
                cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                UIModule.CloseDialog(topDialog)
            else
                local FishingMgr = import('Game.UI.Fishing.FishingMgr')
                local id = FishingMgr:GetInstance()._curFishPlaceId
                if checkNumber(id) > 0 then
                    UIModule.CloseDialog(topDialog)
                    cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
                    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                else
                    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                    UIModule.CloseDialog(topDialog)
                end
            end
            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))

        end
        blocker:RemoveCondition("GOHomeBlocker")
    end)
end

function UINavigatorBar:OnInfoTipButtonAction()
    local curDialog = UIModule.CurrentScreen:LastDialog()
    local moduleId = checkInt(curDialog.Argument.id)
    local env = curDialog.Env
    if env and env.OnTipsAction then
        ---特殊处理下
        env:OnTipsAction()
        return
    end
    if not isNull(KTool.IsActive(curDialog)) and KTool.IsActive(self.InfoTipIcon.gameObject) and moduleId > 0 then
        CfUtils.ShowModuleToast(curDialog.Argument.id)
    end
end

---SetBackShow
---设置是否返回是否显示与否
---@param isShow boolean
function UINavigatorBar:SetBackShow(isShow)
    KTool.SetActive(self.BackButton.gameObject, checkBool(isShow))
end

---SetTipInfoShow
---设置是否返回是否显示与否
---@param isShow boolean
function UINavigatorBar:SetTipInfoShow(isShow)
    local isActive = self.InfoTipButton.gameObject.activeSelf
    isShow = checkBool(isShow)
    if isActive ~= isShow then
        KTool.SetActive(self.InfoTipButton.gameObject, isShow)
    end
end

---SetRightShow
---设置右侧资源条是否显示
---@param isShow boolean
---@param goodsIds number[]
function UINavigatorBar:SetRightShow(isShow, goodsIds)
    isShow = checkBool(isShow)
    self:SetHealthNodeBgShow(isShow)
    if isShow and goodsIds then
        self:UpdateHealthNodes(goodsIds)
    end
end

---SetGameObjectShow
---@param isShow boolean
function UINavigatorBar:SetGameObjectShow(isShow)
    KTool.SetActive(self.controller, checkBool(isShow))
end

---SetHealthNodeBgShow
---设置货币条背景是否显示
---@param isShow boolean
function UINavigatorBar:SetHealthNodeBgShow(isShow)
    KTool.SetActive(self.HealthNode.gameObject, checkBool(isShow))
end

function UINavigatorBar:OnEventChangeTitleName(name, isHideInfoTipIcon)
    local isShowName = not string.isEmpty(name)
    KTool.SetActive(self.InfoTipButton.gameObject, isShowName)
    if isShowName then
        self.TitleText.text = name
    end
    KTool.SetActive(self.InfoTipIcon.gameObject, not isHideInfoTipIcon)
end

function UINavigatorBar:CustomTitleName(name)
    if (not IsNull(self.TitleText)) and (not string.isEmpty(name)) then
        KTool.SetActive(self.TitleText.gameObject, true)
        self.TitleText.text = name
    end
end

---SetHomeShow
---设置是否显示home按钮
---@param isShow boolean
function UINavigatorBar:SetHomeShow(isShow)
    KTool.SetActive(self.HomeBtn.gameObject, isShow)

end

function UINavigatorBar:GetInfoTipButtonGraphic()
    if isNull(self.infoTipButtonGraphic) then
        self.infoTipButtonGraphic = self.InfoTipButton.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Extensions.NonDrawingGraphic))
    end 
    return self.infoTipButtonGraphic
end

function UINavigatorBar:EnableInfoTipButtonGraphic(isEnable)
    local graphic = self:GetInfoTipButtonGraphic()
    if isNotNull(graphic) then
        graphic.raycastTarget = isEnable
    end
end

--- 根据 道具id 获取icon节点
---@param goodsId integer
---@returnn UnityEngine.RectTransform | nil @icon图标节点
function UINavigatorBar:GetAssetNodeIconById(goodsId)
    for i, healthNode in ipairs(self.healthNodes) do
        if KTool.IsActive(healthNode.gameObject) then
            ---@type AssetNodeMB
            local Env = CfUtils.GetLuaScr(healthNode.gameObject, AssetNodeMB)
            if not isNull(Env) and Env:GetGoodsId() == goodsId then
                return Env:GetIcon()
            end
        end
    end
end

--通用的入口按钮绘制
function UINavigatorBar:FillEntrance(data, cb)
    if not data then
        return
    end
    local go = self.HealthNode.transform:Find("entrance")
    if not go then
        CS.Engine.Modules.ResourceModule.LoadGameObjectAsync("Prefabs/Common/CommonEntrance.prefab", function(go)
            if go then
                go.name = "entrance"
                KTool.SetActive(go, true)

                local env = CfUtils.GetLuaScr(go, "Game.UI.Common.CommonEntranceNode")
                if env then
                    env:RefeshSelf(data, cb)
                end
            end
        end)
    end

end

--关闭通用的入口按钮绘制
function UINavigatorBar:CloseEntrance()
    local go = self.HealthNode.transform:Find("entrance")
    if go then
        KTool.SetActive(go, false)
    end
end

function UINavigatorBar:OnDestroy()
    Events.RemoveListener(ANDROID_NATIVE_BACK_ACTION, self.backEventHandler)
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.__everythingChangeHandler)
    Events.RemoveListener(Constants.EventNames.EventChangeNavigatorBarTitleName, self.__EventChangeTitleName)
    self.controller = nil
    self:Delete()
    self = nil
end
return UINavigatorBar